#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.047190710000000004, 0.07989297000000001, 0.269667835], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.11326946000000002, 'zmax': 0.11326946000000002, 'profiles': [{'outer': [[-0.23004898499999998, -0.15765438], [-0.228095795, -0.14474652], [-0.22370824499999997, -0.13229153], [-0.21643337499999998, -0.12096883], [-0.20760169499999997, -0.11075009000000001], [-0.19729807499999996, -0.10058797000000001], [-0.17569997499999995, -0.08201877], [-0.16497173499999995, -0.07205481000000001], [-0.15588524499999995, -0.06243051000000001], [-0.14855381499999998, -0.05119274000000001], [-0.14478900499999997, -0.039303910000000004], [-0.14263769499999995, -0.026396010000000004], [-0.14156201499999999, -0.012808780000000006], [-0.13989195499999996, 0.0006368999999999958], [-0.13689139499999997, 0.013856169999999987], [-0.13250389499999998, 0.026650839999999995], [-0.12689915499999999, 0.03870947999999999], [-0.11965259499999997, 0.0501171], [-0.110877485, 0.06019427999999999], [-0.10128155499999997, 0.06950719999999999], [-0.091911945, 0.07822569999999998], [-0.08319345499999997, 0.08768012], [-0.07722076499999997, 0.09795549], [-0.07238033499999996, 0.10902346999999998], [-0.063661845, 0.13186700999999998], [-0.05867984499999995, 0.14369919], [-0.05052754499999995, 0.15904148999999998], [-0.04345080499999998, 0.17064717000000001], [-0.033656624999999996, 0.18290396999999997], [-0.021116764999999982, 0.1940852], [-0.008633464999999951, 0.20206764], [0.004755585000000007, 0.20900276], [0.016078325000000004, 0.214098], [0.032269765000000034, 0.22052368], [0.04880090500000003, 0.22547736000000002], [0.06578494500000001, 0.22853442000000002], [0.08177827500000001, 0.23011967], [0.10238556500000001, 0.23187467], [0.11849211500000001, 0.23077067], [0.13250395500000003, 0.22870429999999997], [0.15152607500000004, 0.2221938], [0.16417920500000002, 0.21718337], [0.17343551500000004, 0.21203157], [0.191212125, 0.19688746000000001], [0.19661871500000003, 0.19040514999999997], [0.208394335, 0.17277010999999998], [0.21872625500000004, 0.15216274999999999], [0.225491555, 0.13005521], [0.22936961500000003, 0.10851385999999999], [0.230332045, 0.08499093999999999], [0.229341275, 0.06520451999999999], [0.22659550500000003, 0.043974419999999986], [0.22331191500000003, 0.024018159999999997], [0.21436697500000002, -0.01507346000000001], [0.20959618276217842, -0.029411609563063632], [0.207799795, -0.03556753000000001], [0.20304428500000002, -0.04816402000000001], [0.19653371500000003, -0.05954332000000001], [0.19285383500000003, -0.06378934], [0.186852815, -0.06939406000000001], [0.181106535, -0.07352684000000001], [0.16415079500000002, -0.08334926000000001], [0.15543232500000004, -0.0881331], [0.14549665500000003, -0.09303019000000001], [0.13524958500000003, -0.09707806000000001], [0.12537056500000002, -0.10013518], [0.11529335500000001, -0.10265449000000001], [0.10501799500000003, -0.10446609000000001], [0.09471434500000003, -0.10607959], [0.08293874500000004, -0.10743830000000001], [0.07192741500000002, -0.10891024], [0.06134069500000003, -0.11069355], [0.05115024500000001, -0.11332608000000001], [0.042686535000000025, -0.11692104], [0.03371331500000002, -0.12193135000000001], [0.025334505000000035, -0.12779085], [0.01746520500000004, -0.13430140000000002], [0.000396255000000012, -0.15006823000000002], [-0.008831764999999991, -0.15813566], [-0.018144634999999965, -0.16572187], [-0.028108624999999998, -0.17237393], [-0.03869536499999998, -0.17775220000000003], [-0.049650105, -0.18194164000000002], [-0.06063309499999997, -0.18511198], [-0.07181426499999999, -0.18664054000000002], [-0.08330681499999998, -0.18689532], [-0.09528055499999999, -0.18630082], [-0.10716941499999999, -0.18497042000000002], [-0.11976584499999998, -0.18301723], [-0.13253220499999996, -0.1812622], [-0.143798325, -0.17996011], [-0.15536667812966384, -0.18018366912658568], [-0.162310925, -0.18191329], [-0.1688700035877849, -0.18533179452903994], [-0.17306747499999997, -0.18893335], [-0.17668909000857358, -0.19377159575614433], [-0.17858728499999998, -0.19765184000000002], [-0.179776165, -0.20201106000000002], [-0.18003091499999996, -0.20571927], [-0.17940816499999995, -0.21290917], [-0.17703047499999996, -0.22570381], [-0.177058785, -0.22856278000000002], [-0.177907975, -0.23054426], [-0.17935159499999997, -0.23187467], [-0.18291827499999996, -0.23176143000000002], [-0.18699440499999997, -0.23026118], [-0.192061335, -0.22810987000000002], [-0.19741132499999997, -0.22508105], [-0.201855505, -0.22225038], [-0.206214695, -0.21871202], [-0.210658815, -0.21440939], [-0.214593435, -0.20999355], [-0.219179185, -0.2043888], [-0.223000555, -0.19818962], [-0.22659554499999995, -0.19003729000000003], [-0.22897329499999997, -0.18137542], [-0.23033204499999999, -0.16942996]], 'holes': []}], 'simplify_tolerance': 9.2749868e-05, 'sketch_entity_count': 150}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
